import "dotenv/config";
import { randomUUID } from "node:crypto";
import {
  afterAll,
  afterEach,
  beforeEach,
  describe,
  expect,
  it,
  vi,
} from "vitest";
import { db } from "@/lib/db";
import type { Prisma } from "@/generated/prisma/client";
import { clearCompletedHistory } from "@/lib/history";
import { readShortlist } from "@/lib/shortlist";
import { createCampaign } from "@/lib/campaigns";
import { countQuotaUsage, hasSuccessfulDelivery } from "@/lib/delivery-usage";
import { cancelQueued } from "@/lib/cancellation";
import {
  exportAccount,
  requestAccountDeletion,
  cleanupDeletedAccount,
  DELETION_DRAIN_MS,
} from "@/lib/account";
import { readFollowUps } from "@/lib/follow-ups";
import { readCampaignProgress } from "@/lib/campaign-progress";
import { storeLocalResume } from "@/lib/storage";
import * as storage from "@/lib/storage";
import { encryptToken } from "@/lib/crypto";
import { mkdir, writeFile, access, rm } from "node:fs/promises";
import path from "node:path";

const mocks = vi.hoisted(() => ({ send: vi.fn(), gmail: vi.fn() }));
vi.mock("@/lib/gmail", async (original) => ({
  ...(await original<typeof import("@/lib/gmail")>()),
  gmailForUser: mocks.gmail,
}));
import { deliverOne, dispatchPending, checkOneReply } from "@/lib/inngest";
const enabled = process.env.MAILLOOP_DB_TESTS === "1";
if (
  enabled &&
  !["localhost", "127.0.0.1"].includes(
    new URL(process.env.DATABASE_URL!).hostname,
  )
)
  throw new Error("Launch tests require a local database.");
let userId: string, otherId: string, contactId: string, templateId: string;
const input = () => ({
  templateId,
  recipientIds: [contactId],
  recipientRoles: { [contactId]: "Engineer" },
  attachResume: false,
  idempotencyKey: randomUUID(),
});
async function queue() {
  const campaign = await createCampaign(userId, input());
  return db.send.findFirstOrThrow({
    where: { campaignId: campaign.id, campaign: { userId } },
  });
}
async function sent(days: number) {
  const send = await queue();
  return db.send.update({
    where: { id: send.id },
    data: {
      status: "SENT",
      deliveryState: "DONE",
      sentAt: new Date(Date.now() - days * 86400000),
    },
  });
}
describe.runIf(enabled)("public launch database invariants", () => {
  beforeEach(async () => {
    vi.restoreAllMocks();
    vi.clearAllMocks();
    userId = randomUUID();
    otherId = randomUUID();
    await db.user.createMany({
      data: [userId, otherId].map((id) => ({
        id,
        email: `${id}@example.test`,
        gmailAuthorized: true,
        encryptedRefreshToken: encryptToken("FAKE-LAUNCH-TOKEN", id),
      })),
    });
    templateId = (
      await db.template.create({
        data: {
          userId,
          name: "Launch template",
          subject: "Hello {{name}}",
          body: "Private snapshot",
        },
      })
    ).id;
    contactId = (
      await db.contact.create({
        data: {
          userId,
          name: "Ada",
          email: `${(contactId = randomUUID())}@example.test`,
          jobRole: "Engineer",
        },
      })
    ).id;
    mocks.gmail.mockResolvedValue({
      email: "[REDACTED_EMAIL]",
      gmail: { users: { messages: { send: mocks.send } } },
    });
    mocks.send.mockResolvedValue({
      data: { id: "gmail-id", threadId: "thread-id" },
    });
  });
  afterEach(async () => {
    vi.restoreAllMocks();
    await db.campaign.deleteMany({
      where: { userId: { in: [userId, otherId] } },
    });
    await db.user.deleteMany({ where: { id: { in: [userId, otherId] } } });
    await rm(path.join(process.cwd(), "uploads", "resumes", userId), {
      recursive: true,
      force: true,
    });
  });
  afterAll(async () => {
    await db.$disconnect();
  });
  it("clears completed details and reminders without resetting quota, duplicates, or other users", async () => {
    const send = await sent(0);
    await db.send.updateMany({
      where: { id: send.id, campaign: { userId } },
      data: {
        gmailMessageId: "message",
        gmailThreadId: "thread",
        error: "private error",
      },
    });
    const otherTemplate = await db.template.create({
      data: { userId: otherId, name: "Other", subject: "Other", body: "Other" },
    });
    const otherContact = await db.contact.create({
      data: { userId: otherId, name: "Other", email: "[REDACTED_EMAIL]" },
    });
    const other = await db.campaign.create({
      data: {
        userId: otherId,
        templateId: otherTemplate.id,
        status: "COMPLETED",
        sends: {
          create: {
            contactId: otherContact.id,
            status: "SENT",
            deliveryState: "DONE",
            body: "Other private body",
          },
        },
      },
    });
    expect(await clearCompletedHistory(userId)).toBe(1);
    expect(
      await db.send.findFirst({ where: { id: send.id, campaign: { userId } } }),
    ).toBeNull();
    expect(await db.deliveryReceipt.findMany({ where: { userId } })).toEqual([
      {
        id: expect.any(String),
        deliveryKey: send.id,
        userId,
        recipientEmail: send.recipientEmail,
        createdAt: send.createdAt,
        sentAt: send.sentAt,
      },
    ]);
    expect(await countQuotaUsage(userId)).toBe(1);
    expect((await readShortlist(userId)).total).toBe(0);
    expect(
      (await readFollowUps(userId, 7, 1, new Date(Date.now() + 8 * 86400000)))
        .total,
    ).toBe(0);
    expect((await exportAccount(userId)).campaigns).toEqual([]);
    expect(
      await readCampaignProgress({ id: userId, nextSendAt: null }, [
        send.campaignId,
      ]),
    ).toBeNull();
    expect(await checkOneReply(userId, send.id)).toBe(false);
    await expect(createCampaign(userId, input())).rejects.toThrow("skipped");
    expect(await clearCompletedHistory(userId)).toBe(0);
    expect(
      await db.send.findFirst({
        where: { campaignId: other.id, campaign: { userId: otherId } },
      }),
    ).toMatchObject({ body: "Other private body", historyDeletedAt: null });
    expect(await db.contact.count({ where: { userId } })).toBe(1);
    expect(await db.template.count({ where: { userId } })).toBe(1);
  });

  it("retains address safeguards, follow-up requests, quota expiry, and idempotency after contact edits and recreation", async () => {
    const campaignInput = input();
    const campaign = await createCampaign(userId, campaignInput);
    const send = await db.send.findFirstOrThrow({
      where: { campaignId: campaign.id, campaign: { userId } },
    });
    const successful = await db.send.update({
      where: { id: send.id },
      data: { status: "SENT", deliveryState: "DONE", sentAt: new Date() },
    });
    await db.campaign.update({
      where: { id: campaign.id, userId },
      data: { role: "Obsolete" },
    });
    await clearCompletedHistory(userId);
    expect(await createCampaign(userId, campaignInput)).toEqual({
      id: campaign.id,
      count: 0,
      skipped: 0,
    });
    expect(
      await db.campaign.findFirst({ where: { id: campaign.id, userId } }),
    ).toMatchObject({ role: "", attachmentId: null });
    expect(await hasSuccessfulDelivery(db, userId, send.recipientEmail)).toBe(
      true,
    );
    expect(await hasSuccessfulDelivery(db, otherId, send.recipientEmail)).toBe(
      false,
    );
    await db.contact.update({
      where: { id: contactId, userId },
      data: { email: "[REDACTED_EMAIL]", followUpRequestedAt: new Date() },
    });
    expect((await readShortlist(userId)).contacts[0]).toMatchObject({
      previouslySent: false,
      lastSent: null,
    });
    await db.contact.deleteMany({ where: { id: contactId, userId } });
    const recreated = await db.contact.create({
      data: {
        userId,
        name: "Recreated",
        email: send.recipientEmail,
        jobRole: "Engineer",
        followUpRequestedAt: new Date(),
      },
    });
    contactId = recreated.id;
    expect((await readShortlist(userId)).contacts[0]).toMatchObject({
      previouslySent: true,
      followUp: true,
      lastSent: successful.sentAt,
    });
    await expect(createCampaign(userId, input())).rejects.toThrow("skipped");
    const followUp = await createCampaign(userId, {
      ...input(),
      resendIds: [contactId],
    });
    expect(followUp.count).toBe(1);
    expect((await readShortlist(userId)).contacts[0].blocked).toBe(true);
    expect(await countQuotaUsage(userId)).toBe(2);
    expect(
      await countQuotaUsage(userId, db, new Date(Date.now() + 86400001)),
    ).toBe(1);
    const followUpSend = await db.send.findFirstOrThrow({
      where: { campaignId: followUp.id, campaign: { userId } },
    });
    await db.send.update({
      where: { id: followUpSend.id },
      data: { status: "SENT", deliveryState: "DONE", sentAt: new Date() },
    });
    await clearCompletedHistory(userId);
    expect((await readShortlist(userId)).total).toBe(0);
    expect(await countQuotaUsage(userId)).toBe(2);
  });

  it("enforces campaign and worker limits using receipts", async () => {
    const send = await sent(0);
    await clearCompletedHistory(userId);
    await db.deliveryReceipt.createMany({
      data: Array.from({ length: 199 }, () => ({
        userId,
        recipientEmail: "[REDACTED_EMAIL]",
        createdAt: send.createdAt,
        sentAt: new Date(),
      })),
    });
    await expect(
      createCampaign(userId, { ...input(), resendIds: [contactId] }),
    ).rejects.toThrow("exceed");
    // Model a queue reservation predating the receipt usage, as a worker must recheck it.
    const queued = await db.send.create({
      data: {
        campaignId: send.campaignId,
        contactId,
        recipientEmail: send.recipientEmail,
      },
    });
    expect(await countQuotaUsage(userId)).toBe(201);
    expect(await deliverOne(userId, queued.id)).toEqual({ outcome: "done" });
    expect(mocks.send).not.toHaveBeenCalled();
    expect(
      await db.send.findUnique({ where: { id: queued.id } }),
    ).toMatchObject({ status: "FAILED", deliveryState: "DONE" });
  });

  it("rolls back receipts and history together when deletion fails", async () => {
    const send = await sent(0);
    const transaction = db.$transaction.bind(db) as (
      callback: (tx: Prisma.TransactionClient) => Promise<number>,
      options?: { timeout: number },
    ) => Promise<number>;
    vi.spyOn(db, "$transaction").mockImplementationOnce(((
      callback: (tx: Prisma.TransactionClient) => Promise<number>,
      options?: { timeout: number },
    ) =>
      transaction(async (tx) => {
        vi.spyOn(tx.campaign, "updateMany").mockRejectedValueOnce(
          new Error("injected cleanup failure"),
        );
        return callback(tx);
      }, options)) as typeof db.$transaction);
    await expect(clearCompletedHistory(userId)).rejects.toThrow(
      "injected cleanup failure",
    );
    expect(
      await db.send.findFirst({ where: { id: send.id, campaign: { userId } } }),
    ).toMatchObject({ body: "Private snapshot" });
    expect(await db.deliveryReceipt.count({ where: { userId } })).toBe(0);
    expect(await countQuotaUsage(userId)).toBe(1);
  });

  it("serializes repeated concurrent deletion without losing or double-counting usage", async () => {
    await sent(0);
    const [first, second, usage] = await Promise.all([
      clearCompletedHistory(userId),
      clearCompletedHistory(userId),
      countQuotaUsage(userId),
    ]);
    expect(first + second).toBe(1);
    expect(usage).toBe(1);
    expect(await countQuotaUsage(userId)).toBe(1);
    expect(await db.deliveryReceipt.count({ where: { userId } })).toBe(1);
    expect(await db.send.count({ where: { campaign: { userId } } })).toBe(0);
  });

  it("preserves queued and unresolved records, clearing failed and cancelled terminal records", async () => {
    const queued = await queue();
    const states = [
      { status: "FAILED" as const, deliveryState: "ATTEMPTING" as const },
      { status: "FAILED" as const, deliveryState: "UNCERTAIN" as const },
      { status: "FAILED" as const, deliveryState: "DONE" as const },
      { status: "CANCELLED" as const, deliveryState: "DONE" as const },
      { status: "REPLIED" as const, deliveryState: "DONE" as const },
    ];
    await db.send.createMany({
      data: states.map((state) => ({
        ...state,
        campaignId: queued.campaignId,
        contactId,
        body: "Preserved unless completed",
      })),
    });
    expect(await clearCompletedHistory(userId)).toBe(3);
    const rows = await db.send.findMany({ where: { campaign: { userId } } });
    // Completed rows in active campaigns are hidden and redacted so their
    // original policy evidence survives history deletion.
    expect(rows.filter((row) => !row.historyDeletedAt)).toHaveLength(3);
    expect(
      rows
        .filter((row) => row.historyDeletedAt)
        .every((row) => row.body === ""),
    ).toBe(true);
    expect(
      rows
        .filter((row) => !row.historyDeletedAt)
        .every((row) => row.body.length > 0),
    ).toBe(true);
    expect(await countQuotaUsage(userId)).toBe(3);
    expect(await deliverOne(userId, queued.id)).toEqual({ outcome: "done" });
    expect(mocks.send).toHaveBeenCalledTimes(1);
  });

  it("does not clear an active Gmail submission", async () => {
    const send = await queue();
    let release!: () => void;
    let claimed!: () => void;
    const submitted = new Promise<void>((resolve) => {
      claimed = resolve;
    });
    mocks.send.mockImplementationOnce(async () => {
      claimed();
      await new Promise<void>((resolve) => {
        release = resolve;
      });
      return { data: { id: "submitted" } };
    });
    const worker = deliverOne(userId, send.id);
    await submitted;
    try {
      expect(await clearCompletedHistory(userId)).toBe(0);
    } finally {
      release();
    }
    await worker;
    expect(
      await db.send.findFirst({ where: { id: send.id, campaign: { userId } } }),
    ).toMatchObject({
      status: "SENT",
      body: "Private snapshot",
      historyDeletedAt: null,
    });
  });

  it("legacy reply helpers do no work before and after history deletion", async () => {
    const send = await sent(8);
    expect(await checkOneReply(userId, send.id)).toBe(false);
    expect(mocks.gmail).not.toHaveBeenCalled();
    expect(await clearCompletedHistory(userId)).toBe(1);
    expect(await checkOneReply(userId, send.id)).toBe(false);
    expect(await hasSuccessfulDelivery(db, userId, send.recipientEmail)).toBe(
      true,
    );
  });

  it("cancels only owned ready sends, releases quota, stops published jobs, and is idempotent", async () => {
    const send = await queue();
    expect(await cancelQueued(otherId, { sendId: send.id })).toEqual({
      cancelled: 0,
      couldNotStop: 0,
    });
    expect(await countQuotaUsage(userId)).toBe(1);
    expect(await cancelQueued(userId, { campaignId: send.campaignId })).toEqual(
      { cancelled: 1, couldNotStop: 0 },
    );
    expect(await cancelQueued(userId, { sendId: send.id })).toEqual({
      cancelled: 0,
      couldNotStop: 0,
    });
    expect(await countQuotaUsage(userId)).toBe(0);
    expect(
      (await db.send.findUniqueOrThrow({ where: { id: send.id } })).cancelledAt,
    ).not.toBeNull();
    expect(await deliverOne(userId, send.id)).toEqual({ outcome: "done" });
    expect(mocks.send).not.toHaveBeenCalled();
    expect(
      (await db.campaign.findUniqueOrThrow({ where: { id: send.campaignId } }))
        .status,
    ).toBe("COMPLETED_WITH_CANCELLATIONS");
    expect(
      await readCampaignProgress({ id: userId, nextSendAt: null }, [
        send.campaignId,
      ]),
    ).toMatchObject({ cancelled: 1, sent: 0, queued: 0, outstanding: 0 });
  });
  it("cannot stop a worker after its claim and retains uncertain reservations", async () => {
    const send = await queue();
    let release!: () => void;
    let claimed!: () => void;
    const waiting = new Promise<void>((resolve) => {
      claimed = resolve;
    });
    mocks.send.mockImplementationOnce(async () => {
      claimed();
      await new Promise<void>((resolve) => {
        release = resolve;
      });
      return { data: { id: "sent" } };
    });
    const worker = deliverOne(userId, send.id);
    await waiting;
    expect(await cancelQueued(userId, { sendId: send.id })).toEqual({
      cancelled: 0,
      couldNotStop: 1,
    });
    release();
    await worker;
    await db.send.update({
      where: { id: send.id },
      data: { status: "FAILED", deliveryState: "UNCERTAIN" },
    });
    expect(await cancelQueued(userId, { campaignId: send.campaignId })).toEqual(
      { cancelled: 0, couldNotStop: 1 },
    );
    expect(await countQuotaUsage(userId)).toBe(1);
  });
  it("deletion during Gmail submission leaves the claimed send alone and blocks new upload activation", async () => {
    const send = await queue();
    let release!: () => void;
    let claimed!: () => void;
    const submitted = new Promise<void>((resolve) => {
      claimed = resolve;
    });
    mocks.send.mockImplementationOnce(async () => {
      claimed();
      await new Promise<void>((resolve) => {
        release = resolve;
      });
      return { data: { id: "already-submitted" } };
    });
    const worker = deliverOne(userId, send.id);
    await submitted;
    expect(
      await requestAccountDeletion(userId, `${userId}@example.test`),
    ).toMatchObject({ cancelled: 0, couldNotStop: 1 });
    expect(await cleanupDeletedAccount(userId)).toBe(false);
    const pathname = `resumes/${userId}/${randomUUID()}.pdf`;
    const full = path.join(process.cwd(), "uploads", pathname);
    await mkdir(path.dirname(full), { recursive: true });
    await writeFile(full, "%PDF-1.7\nnot activated");
    await expect(
      storage.activateResume(userId, pathname, "upload.pdf"),
    ).rejects.toThrow("Account unavailable");
    expect(await db.attachment.count({ where: { userId } })).toBe(0);
    release();
    await worker;
    expect(
      (await db.send.findUniqueOrThrow({ where: { id: send.id } })).status,
    ).toBe("SENT");
    expect(
      (await db.user.findUniqueOrThrow({ where: { id: userId } }))
        .gmailAuthorized,
    ).toBe(false);
  });
  it("exports only owned explicit fields and excludes credentials and storage paths", async () => {
    const send = await sent(10);
    await db.attachment.create({
      data: {
        userId,
        fileName: "cv.pdf",
        storagePath: `resumes/${userId}/${randomUUID()}.pdf`,
      },
    });
    await db.contact.create({
      data: {
        userId: otherId,
        name: "OTHER-PRIVATE",
        email: "[REDACTED_EMAIL]",
      },
    });
    const data = await exportAccount(userId);
    const json = JSON.stringify(data);
    expect(data.version).toBe(2);
    expect(data.profile.followUpDays).toBe(7);
    expect(data.campaigns[0].sends[0]).toMatchObject({
      id: send.id,
      body: "Private snapshot",
    });
    for (const secret of [
      "encryptedRefreshToken",
      "storagePath",
      "googleId",
      "FAKE-LAUNCH-TOKEN",
      "OTHER-PRIVATE",
      "idempotencyKey",
    ])
      expect(json).not.toContain(secret);
  });
  it("account deletion does not enumerate completed history as work to cancel", async () => {
    const send = await sent(10);
    expect(
      await requestAccountDeletion(userId, `${userId}@example.test`),
    ).toEqual({ cancelled: 0, couldNotStop: 0 });
    expect(
      (await db.send.findUniqueOrThrow({ where: { id: send.id } })).status,
    ).toBe("SENT");
  });
  it("deletion disables work immediately, purges after the drain, and retries storage independently", async () => {
    await storeLocalResume(
      userId,
      new File(["%PDF-1.7\nactivated"], "active.pdf", {
        type: "application/pdf",
      }),
    );
    const attachment = await db.attachment.findFirstOrThrow({
      where: { userId },
    });
    const activatedPath = path.join(
      process.cwd(),
      "uploads",
      attachment.storagePath,
    );
    const successful = await sent(0);
    await db.campaign.updateMany({
      where: { id: successful.campaignId, userId },
      data: { attachmentId: attachment.id },
    });
    await clearCompletedHistory(userId);
    expect(
      await db.campaign.findFirst({
        where: { id: successful.campaignId, userId },
      }),
    ).toMatchObject({ attachmentId: null });
    await access(activatedPath);
    await db.contact.create({
      data: {
        userId,
        name: "Pending",
        email: `${randomUUID()}@example.test`,
        jobRole: "Engineer",
      },
    });
    const pendingContact = await db.contact.findFirstOrThrow({
      where: { userId, id: { not: contactId } },
    });
    const campaign = await createCampaign(userId, {
      ...input(),
      recipientIds: [pendingContact.id],
      recipientRoles: { [pendingContact.id]: "Engineer" },
    });
    const send = await db.send.findFirstOrThrow({
      where: { campaignId: campaign.id, campaign: { userId } },
    });
    expect(await db.deliveryReceipt.count({ where: { userId } })).toBe(1);
    await expect(
      requestAccountDeletion(userId, "[REDACTED_EMAIL]"),
    ).rejects.toThrow("exactly");
    expect(
      await requestAccountDeletion(userId, `${userId}@example.test`),
    ).toMatchObject({ cancelled: 1 });
    await expect(createCampaign(userId, input())).rejects.toThrow(
      "unavailable",
    );
    await expect(
      storage.activateResume(userId, "invalid", "cv.pdf"),
    ).rejects.toThrow();
    expect(await deliverOne(userId, send.id)).toEqual({ outcome: "done" });
    expect(await dispatchPending(userId)).toBe(0);
    expect(await checkOneReply(userId, send.id)).toBe(false);
    await expect(exportAccount(userId)).rejects.toThrow("unavailable");
    expect(await cleanupDeletedAccount(userId)).toBe(false);
    const unactivated = path.join(
      process.cwd(),
      "uploads",
      "resumes",
      userId,
      `${randomUUID()}.pdf`,
    );
    await mkdir(path.dirname(unactivated), { recursive: true });
    await writeFile(unactivated, "%PDF-1.7\nprivate");
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      new Response("", { status: 200 }),
    );
    const deletion = vi
      .spyOn(storage, "deleteOwnedResumes")
      .mockRejectedValueOnce(new Error("storage unavailable"));
    const requestedAt = (
      await db.user.findUniqueOrThrow({
        where: { id: userId },
      })
    ).deletionRequestedAt!;
    await requestAccountDeletion(userId, `${userId}@example.test`);
    expect(
      (
        await db.user.findUniqueOrThrow({
          where: { id: userId },
        })
      ).deletionRequestedAt,
    ).toEqual(requestedAt);
    const future = new Date(requestedAt.getTime() + DELETION_DRAIN_MS);
    expect(
      await cleanupDeletedAccount(userId, new Date(future.getTime() - 1)),
    ).toBe(false);
    expect(globalThis.fetch).not.toHaveBeenCalled();
    expect(deletion).not.toHaveBeenCalled();
    await expect(access(unactivated)).resolves.toBeUndefined();
    await db.accountDeletionJob.update({
      where: { userId },
      data: { nextAttemptAt: requestedAt },
    });
    expect(await cleanupDeletedAccount(userId, future)).toBe(false);
    expect(await db.contact.count({ where: { userId } })).toBe(0);
    expect(await db.template.count({ where: { userId } })).toBe(0);
    expect(await db.attachment.count({ where: { userId } })).toBe(0);
    expect(await db.send.findUnique({ where: { id: send.id } })).toBeNull();
    expect(await db.user.findUnique({ where: { id: userId } })).toBeNull();
    expect(
      await db.accountDeletionJob.findUnique({ where: { userId } }),
    ).toMatchObject({
      contentDeletedAt: future,
      storageDeletedAt: null,
      billingCancelledAt: expect.any(Date),
    });
    deletion.mockRestore();
